content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体的法律存续状态与经营资质合规性",
            "check_points": [
                "通过国家企业信用信息公示系统或司法大数据平台核查该主体是否存在未结重大诉讼、仲裁、被执行、失信、严重违法等涉法涉诉记录",
                "核对营业执照登记的经营范围，确认本合同项下标的（如服务内容、产品类型、技术授权等）属于其法定经营范围之内",
                "逐项比对合同首部所载主体信息（名称、统一社会信用代码、注册地址、联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "若合同涉及软件、算法、源代码、数据库等采购或定制开发，须核查卖方/开发方是否拥有相关核心知识产权（如著作权登记证书、专利证书、权利归属声明），或已获得合法有效的授权链条"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同核心条款体系完整、要素齐备、逻辑自洽",
            "check_points": [
                "检查合同是否完整涵盖以下必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用限制、产品质量标准与保证、交付方式与地点、验收标准与程序、完成时限（含里程碑节点）、违约责任（含违约金计算方式与上限）、争议解决方式（含管辖法院/仲裁机构）、不可抗力定义与处理机制、廉洁承诺条款、合同变更程序、合同份数及效力说明、电子送达约定（含有效邮箱/短信号码及法律效力确认）",
                "确认合同中已明确指定主要项目负责人，并完整载明其姓名、身份证号码（或统一社会信用代码）、联系电话及授权权限",
                "采购内容须具体列明品种、规格、型号、等级、花色、技术参数、数量单位等关键要素；如内容复杂，须以附件形式固化并注明‘附件为本合同不可分割组成部分’",
                "合同金额须同时载明：标的物单价、数量、总价、计量单位、币种（如人民币/USD）、大小写一致；总价应与各分项汇总严格吻合；禁止出现‘暂定’‘约’‘大致’等模糊表述",
                "付款计划须明确划分付款阶段（如预付款、到货款、验收款、质保金），注明各阶段触发条件（如书面签收、验收合格报告签署、维保期届满）、支付比例、到账时限；质保金比例不低于5%，且须约定于免费维保期（不少于12个月）届满后无息返还；同步注明发票类型（专票/普票）、开票时间及税目税率"
            ]
        },
        {
            "id": "C3",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限约定精确、无歧义，明确时间计算规则",
            "check_points": [
                "合同期限须以起止日期（YYYY-MM-DD格式）或明确周期（如‘自2025年1月1日起至2026年12月31日止’）方式载明，禁止仅写‘一年期’等模糊表述",
                "所有时间节点（如交付日、验收日、付款日、终止日）须明示采用‘自然日’或‘工作日’；如约定季度/月度周期，须注明计算方式（如‘自起始日起满3个自然月之最后一日’或‘自起始日起第90个自然日’），避免‘第三个月末’等易生歧义表述"
            ]
        },
        {
            "id": "C4",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同文本形式严谨、语言准确、内外统一",
            "check_points": [
                "全文通读排查错别字、标点误用、语法错误、语序混乱、主谓不一致等文字硬伤",
                "逐条比对正文与所有附件（含技术规格书、服务清单、报价明细、保密协议等）中相同条款（如付款条件、验收标准、知识产权归属、违约责任）的表述是否完全一致，存在差异时须以正文为准并加注说明",
                "清除合同正文中残留的招标、谈判、比选等采购流程相关术语（如‘投标文件’‘响应文件’‘评标委员会’‘中标通知书’），统一替换为‘本合同’‘双方’‘甲方/乙方’等契约化表述",
                "核验合同首部‘甲方/乙方’全称、签约页落款名称、印章名称三者完全一致；若使用简称，须在首部明确定义（如‘以下简称“甲方”’）并在全文统一使用",
                "核查合同中援引的法律法规、部门规章、强制性标准名称及文号（如《民法典》第五百零九条、GB/T 19001-2016）是否现行有效，不得引用已废止或尚未施行的规范性文件",
                "确认合同正文末尾独立成行标注‘以下为合同签署栏’或‘以下无正文’字样，且该行与签署栏之间无任何空白行或冗余内容"
            ]
        }
    ]
}
